# Initially generated by GitHub Copilot.

import unittest
from pathlib import Path
from tempfile import TemporaryDirectory

from mb_cmn import provenance
from pipeline_graph import pipeline_graph
from tmpl_survey import survey_dot


class TestGraphProvenance(unittest.TestCase):
    @staticmethod
    def _generated_by() -> str:
        return provenance.generated_by_text(str(Path(__file__).resolve()))

    def test_write_dot_file_includes_provenance_comments(self):
        stack_counts = {("מ:פסוק", "C/מ:כפול"): 3}
        expected = self._generated_by()
        with TemporaryDirectory() as tmp_dir:
            dot_path = Path(tmp_dir) / "graph.dot"
            survey_dot.write_dot_file(
                stack_counts,
                str(dot_path),
                generator_file=__file__,
            )
            dot_text = dot_path.read_text(encoding="utf-8")

        self.assertIn(f"// {expected}", dot_text)
        self.assertIn(f"graph [comment={survey_dot._dot_quoted(expected)}];", dot_text)
        self.assertIn("have been discarded", dot_text)

    def test_write_focused_dot_files_include_provenance_comments(self):
        stack_counts = {
            ("מ:כפול", "C"): 2,
            ("נוסח", "D"): 1,
        }
        expected = self._generated_by()
        with TemporaryDirectory() as tmp_dir:
            stem = Path(tmp_dir) / "focused"
            survey_dot.write_focused_dot_files(
                stack_counts,
                str(stem),
                generator_file=__file__,
            )
            kaful_text = (Path(tmp_dir) / "focused-kaful-call-graph.dot").read_text(
                encoding="utf-8"
            )
            nusach_text = (Path(tmp_dir) / "focused-nusach-call-graph.dot").read_text(
                encoding="utf-8"
            )

        self.assertIn(f"// {expected}", kaful_text)
        self.assertIn(f"// {expected}", nusach_text)
        self.assertIn(
            f"graph [comment={survey_dot._dot_quoted(expected)}];",
            kaful_text,
        )

    def test_svg_fallback_comment_insertion_is_idempotent(self):
        expected = self._generated_by()
        with TemporaryDirectory() as tmp_dir:
            svg_path = Path(tmp_dir) / "graph.svg"
            svg_path.write_text(
                '<?xml version="1.0" encoding="UTF-8"?>\n'
                '<svg xmlns="http://www.w3.org/2000/svg"></svg>\n',
                encoding="utf-8",
            )
            survey_dot._ensure_svg_comment(str(svg_path), expected)
            survey_dot._ensure_svg_comment(str(svg_path), expected)
            svg_text = svg_path.read_text(encoding="utf-8")

        marker = f"<!-- {expected} -->"
        self.assertEqual(svg_text.count(marker), 1)
        self.assertLess(svg_text.find(marker), svg_text.find("<svg "))

    def test_pipeline_dot_text_includes_provenance_comment(self):
        expected = self._generated_by()
        dot_text = pipeline_graph.render_dot_text(generator_file=__file__)
        self.assertIn(f"// {expected}", dot_text)
        self.assertIn(
            f"graph [comment={pipeline_graph._quote_dot(expected)}];",
            dot_text,
        )
        self.assertIn(
            "edit py/pipeline_graph/pipeline_graph_spec.py instead.",
            dot_text,
        )


if __name__ == "__main__":
    unittest.main()
